/* Actual normal ARM/CLIENT cached-TCP and per-attempt Unix read points. */
#include "platform.h"
#include "gnunet_util_lib.h"
#include "gnunet_arm_service.h"
static struct GNUNET_CONFIGURATION_Handle*cfg;static struct GNUNET_ARM_Handle*owner;static struct GNUNET_SCHEDULER_Task *watchdog,*change;static const char*new_unix;static unsigned new_port;static int updated,confirmed,listed,failed,finishing;
static void finish(void*cls){(void)cls;if(finishing)return;finishing=1;if(watchdog){GNUNET_SCHEDULER_cancel(watchdog);watchdog=NULL;}if(change){GNUNET_SCHEDULER_cancel(change);change=NULL;}if(owner){struct GNUNET_ARM_Handle*old=owner;owner=NULL;GNUNET_ARM_disconnect(old);}GNUNET_SCHEDULER_shutdown();}
static void late(void*cls){(void)cls;watchdog=NULL;failed=1;finish(NULL);}
static void connection(void*cls,enum GNUNET_GenericReturnValue status){(void)cls;printf("{\"event\":\"connection\",\"status\":%d,\"unix_updated\":%s}\n",status,updated?"true":"false");if(status==GNUNET_YES){confirmed++;if(!updated){failed=1;GNUNET_SCHEDULER_add_now(&finish,NULL);}}else{failed=1;GNUNET_SCHEDULER_add_now(&finish,NULL);}}
static void list(void*cls,enum GNUNET_ARM_RequestStatus status,unsigned count,const struct GNUNET_ARM_ServiceInfo*rows){(void)cls;(void)rows;listed++;printf("{\"event\":\"list\",\"status\":%u,\"count\":%u,\"unix_updated\":%s}\n",status,count,updated?"true":"false");if(status!=GNUNET_ARM_REQUEST_SENT_OK||count||!updated)failed=1;GNUNET_SCHEDULER_add_now(&finish,NULL);}
static void change_unix(void*cls){(void)cls;change=NULL;GNUNET_CONFIGURATION_set_value_string(cfg,"arm","UNIXPATH",new_unix);updated=1;puts("{\"event\":\"unix-updated\"}");}
static void run(void*cls){(void)cls;owner=GNUNET_ARM_connect(cfg,&connection,NULL);if(!owner){failed=1;finish(NULL);return;}if(!GNUNET_ARM_request_service_list(owner,&list,NULL)){failed=1;finish(NULL);return;}GNUNET_CONFIGURATION_set_value_number(cfg,"arm","PORT",new_port);puts("{\"event\":\"port-updated\"}");change=GNUNET_SCHEDULER_add_delayed(GNUNET_TIME_relative_multiply(GNUNET_TIME_UNIT_MILLISECONDS,40),&change_unix,NULL);watchdog=GNUNET_SCHEDULER_add_delayed(GNUNET_TIME_relative_multiply(GNUNET_TIME_UNIT_SECONDS,14),&late,NULL);}
int main(int argc,char**argv){if(argc!=5)return 90;setvbuf(stdout,NULL,_IOLBF,0);GNUNET_log_setup("owned-client-live-config","ERROR",NULL);new_unix=argv[2];new_port=(unsigned)strtoul(argv[4],NULL,10);cfg=GNUNET_CONFIGURATION_create(GNUNET_OS_project_data_gnunet());GNUNET_CONFIGURATION_set_value_string(cfg,"arm","UNIXPATH",argv[1]);GNUNET_CONFIGURATION_set_value_number(cfg,"arm","PORT",strtoul(argv[3],NULL,10));GNUNET_CONFIGURATION_set_value_string(cfg,"arm","HOSTNAME","127.0.0.1");GNUNET_SCHEDULER_run(&run,NULL);GNUNET_CONFIGURATION_destroy(cfg);printf("{\"event\":\"done\",\"confirmed\":%d,\"listed\":%d,\"failed\":%d}\n",confirmed,listed,failed);return failed||confirmed!=1||listed!=1;}
